SELECT CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN city = 'London' THEN rating ELSE 0 END) AS london_rating FROM suppliers WHERE country NOT IN ('SG', 'DE') AND city = 'Bangkok' AND LOWER(TRIM(supplier_name)) = 'siam parts co' GROUP BY CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 1.6 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket DESC;
